  const f = new Date(Date.UTC(y, m - 1, d, 15));
  _FMT_LARGA = _FMT_LARGA || new Intl.DateTimeFormat("es-CL", { timeZone: TZ, weekday: "long", day: "numeric", month: "long", year: "numeric" });
