const HORO_ANUAL_CSS = "<style id=\"cnHoroAnual\">\n.horo .vista-horo{gap:10px;max-width:640px}\n.horo .vista-horo.cn-cuatro{grid-template-columns:repeat(4,minmax(0,1fr));max-width:1040px}\n@media (max-width:760px){.horo .vista-horo.cn-cuatro{grid-template-columns:repeat(2,minmax(0,1fr))}}\n.horo .vista-horo .horo-btn{align-items:center;justify-content:center;text-align:center;padding:12px 14px;min-height:58px}\n.horo .vista-horo .horo-btn .mn{font:700 17px/1.25 var(--sans);color:var(--tinta);text-wrap:balance}\n@media (max-width:560px){.horo .vista-horo .horo-btn{padding:10px 8px;min-height:62px}.horo .vista-horo .horo-btn .mn{font-size:15.5px}}\n.vista-horo .ha-l-en{display:none}.horo.cn-en .vista-horo .ha-l-es{display:none}.horo.cn-en .vista-horo .ha-l-en{display:inline}\n.horo .horo-anual{display:none;margin-top:22px}.horo[data-vista=\"anio\"] .horo-anual,.horo[data-vista=\"chino\"] .horo-anual{display:block}\n.horo[data-vista=\"anio\"] .signos,.horo[data-vista=\"chino\"] .signos{display:none}\n.horo-anual .ha-zod,.horo-anual .ha-chi{display:none}.horo[data-vista=\"anio\"] .ha-zod,.horo[data-vista=\"chino\"] .ha-chi{display:block}\n.horo-anual .ha-b-en{display:none}.horo.cn-en .horo-anual .ha-b-es{display:none}.horo.cn-en .horo-anual .ha-b-en{display:block}\n.ha-perfil{background:var(--card,var(--papel));border:1.5px solid var(--oro);border-radius:14px;padding:16px 18px;margin:0 0 18px}\n.ha-perfil h3,.ha-intro h3{margin:0 0 6px;font:700 22px/1.2 var(--serif);color:var(--tinta)}\n.hp-filas{display:grid;grid-template-columns:1fr;gap:10px;margin-top:10px}@media (min-width:880px){.hp-filas{grid-template-columns:1fr 1.35fr}}\n.hp-f{border:1px solid var(--linea);border-radius:10px;padding:6px 12px 12px;margin:0;display:flex;flex-wrap:wrap;gap:10px;min-width:0}\n.hp-f legend{font:700 14px var(--sans);color:var(--oro-texto,#8A6416);padding:0 6px}\n.hp-f label{display:flex;flex-direction:column;gap:4px;font:600 13.5px var(--sans);color:var(--gris);flex:1 1 104px;min-width:0}\n.hp-f select,.ha-calc select{font:600 15.5px var(--sans);padding:8px 10px;border:1px solid var(--linea);border-radius:8px;background:var(--card,var(--papel));color:var(--tinta);min-height:44px;width:100%;max-width:100%}\n.hp-priv{margin:12px 0 0;font-size:13.5px;line-height:1.45;color:var(--gris);display:flex;flex-wrap:wrap;align-items:center;gap:8px 12px}\n.hp-borrar{font-size:13.5px;padding:8px 14px}\n.hp-res{margin-top:14px}.hp-vacio{margin:0;color:var(--gris);font-size:15px}\n.hp-res-t{margin:0 0 10px;font:700 19px var(--serif);color:var(--tinta)}\n.hp-res-g{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:10px}\n.hp-i{border:1px solid var(--linea);border-radius:10px;padding:12px 14px;display:flex;flex-direction:column;gap:5px;background:var(--papel)}\n.hp-k{font:700 12px var(--sans);letter-spacing:.6px;text-transform:uppercase;color:var(--oro-texto,#8A6416)}\n.hp-i b{font:700 18px/1.25 var(--serif);color:var(--tinta)}.hp-i .hp-b2{margin-top:4px}\n.hp-d{font-size:14.5px;line-height:1.5}.hp-s{font-size:14px;line-height:1.6}.hp-s .estr{margin-left:2px}\n.hp-ir{align-self:flex-start;margin-top:6px;font-size:14px}\n.ha-intro{background:var(--card,var(--papel));border:1px solid var(--linea);border-radius:14px;padding:16px 18px}\n.ha-intro h4{margin:16px 0 4px;font:700 17px var(--serif);color:var(--tinta)}\n.ha-lead{margin:0 0 10px;color:var(--gris);font-size:15px;line-height:1.5}.hc-como{margin-top:8px}\n.ha-cielo{margin:0;padding-left:18px}.ha-cielo li{margin:7px 0;font-size:15px;line-height:1.55}\n.ha-elem{display:flex;height:10px;border-radius:999px;overflow:hidden;margin:6px 0 6px;max-width:420px;background:var(--linea)}\n.ha-elem i{display:block;min-width:4px}.ha-elem .e0{background:#C2502E}.ha-elem .e1{background:#5B7F3A}.ha-elem .e2{background:#C9A227}.ha-elem .e3{background:#2F6DA3}\n.ha-elige{margin:24px 0 10px;font:700 19px var(--serif);color:var(--tinta)}\n.ha-chips{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px}\n@media (max-width:760px){.ha-chips{grid-template-columns:repeat(4,minmax(0,1fr))}}@media (max-width:420px){.ha-chips{grid-template-columns:repeat(3,minmax(0,1fr))}}\n.ha-chip{all:unset;box-sizing:border-box;cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;padding:9px 4px 8px;min-height:44px;\nborder:1px solid var(--linea);border-radius:10px;background:var(--card,var(--papel));box-shadow:0 2px 6px rgba(11,31,58,.1),0 1px 2px rgba(11,31,58,.06);text-align:center;\ntransition:box-shadow .15s,border-color .15s,transform .15s;touch-action:manipulation;-webkit-tap-highlight-color:rgba(184,137,43,.18)}\n.ha-chip b{font:700 13.5px/1.2 var(--sans);color:var(--tinta);overflow-wrap:anywhere}.ha-chip:hover{border-color:var(--oro);transform:translateY(-1px)}\n.ha-chip:focus-visible{outline:2px solid var(--oro);outline-offset:2px}.ha-chip[aria-pressed=\"true\"]{border-color:var(--oro);box-shadow:inset 0 -3px 0 var(--oro),0 4px 12px rgba(11,31,58,.14)}\n.ha-med{display:inline-flex;line-height:0}.ha-chip .ha-med:empty{display:none}\n.hc-glifo{display:inline-flex;align-items:center;justify-content:center;flex:none;width:34px;height:34px;border-radius:50%;background:#0B1F3A;color:#F3D27A;border:2px solid #D9AE52;\nfont:700 19px/1 \"Noto Serif CJK SC\",\"Noto Serif CJK TC\",\"Songti SC\",\"PingFang SC\",\"Microsoft YaHei\",\"SimSun\",serif}\n.hc-animal header .hc-glifo{width:56px;height:56px;font-size:31px;border-width:3px}.hc-glifo.hc-mini{width:26px;height:26px;font-size:15px;vertical-align:-5px;border-width:1.5px}\n.ha-pide{margin:14px 0 0;color:var(--gris);font-size:15px}.ha-con .ha-pide,.horo-anual:not(.ha-js) .ha-pide{display:none}\n.horo-anual:not(.ha-js) .ha-chips,.horo-anual:not(.ha-js) .ha-elige,.horo-anual:not(.ha-js) .ha-perfil{display:none}\n.horo-anual.ha-js .ha-signo,.horo-anual.ha-js .hc-animal{display:none}.horo-anual.ha-js .ha-signo.ha-sel,.horo-anual.ha-js .hc-animal.ha-sel{display:block}\n.ha-signo,.hc-animal{margin-top:14px;break-inside:auto}.ha-signo .ha-med svg{display:block}\n.ha-signo .ha-txt,.hc-animal .ha-txt{font-size:15.5px;line-height:1.6;margin:8px 0 10px}.hc-rel{margin:8px 0 0;font-size:15px}\n.ha-signo h4{margin:18px 0 6px;font:700 17px var(--serif);color:var(--tinta)}\n.ha-meses{margin:12px 0 2px;font-size:15px;line-height:1.5}\n.ha-mm{list-style:none;margin:0;padding:0}.ha-mm li{display:grid;grid-template-columns:7.4em 5.6em 1fr;gap:4px 10px;align-items:baseline;padding:8px 0;border-top:1px solid var(--linea);font-size:15px;line-height:1.5}\n.ha-mm li .estr{margin-left:0}@media (max-width:560px){.ha-mm li{grid-template-columns:auto 1fr}.ha-mm li .t{grid-column:1/-1}}\n.ha-fechas{margin:0;padding-left:18px}.ha-fechas li{margin:6px 0;font-size:15px;line-height:1.5}\n.ha-metodo{margin:16px 0 0;font-size:13px;color:var(--gris);line-height:1.5}\n@media (prefers-reduced-motion:reduce){.ha-chip,.ha-chip:hover{transition:none;transform:none}}\n@media print{.horo:not([data-vista=\"anio\"]):not([data-vista=\"chino\"]) .horo-anual{display:none!important}.horo[data-vista=\"anio\"] .signos,.horo[data-vista=\"chino\"] .signos{display:none!important}\n.horo-anual .ha-chips,.horo-anual .ha-elige,.horo-anual .ha-pide,.horo-anual .hp-filas,.horo-anual .hp-priv,.horo-anual .hp-ir{display:none!important}\n.horo-anual .ha-zod:not(.ha-con) .ha-signo,.horo-anual .ha-chi:not(.ha-con) .hc-animal{display:block!important}.ha-intro,.ha-signo,.hc-animal,.ha-perfil{box-shadow:none}}\n</style>";
const HORO_ANUAL_JS = "<script>(function(){\nvar P=document.getElementById('horoAnual');if(!P)return;var H=P.closest('.horo');if(!H)return;\nP.classList.add('ha-js');var R=document.documentElement,ANIO=+P.getAttribute('data-anio');\nvar CNY={\"1919\": \"02-01\", \"1920\": \"02-20\", \"1921\": \"02-08\", \"1922\": \"01-28\", \"1923\": \"02-16\", \"1924\": \"02-05\", \"1925\": \"01-24\", \"1926\": \"02-13\", \"1927\": \"02-02\", \"1928\": \"01-23\", \"1929\": \"02-10\", \"1930\": \"01-30\", \"1931\": \"02-17\", \"1932\": \"02-06\", \"1933\": \"01-26\", \"1934\": \"02-14\", \"1935\": \"02-04\", \"1936\": \"01-24\", \"1937\": \"02-11\", \"1938\": \"01-31\", \"1939\": \"02-19\", \"1940\": \"02-08\", \"1941\": \"01-27\", \"1942\": \"02-15\", \"1943\": \"02-05\", \"1944\": \"01-25\", \"1945\": \"02-13\", \"1946\": \"02-02\", \"1947\": \"01-22\", \"1948\": \"02-10\", \"1949\": \"01-29\", \"1950\": \"02-17\", \"1951\": \"02-06\", \"1952\": \"01-27\", \"1953\": \"02-14\", \"1954\": \"02-03\", \"1955\": \"01-24\", \"1956\": \"02-12\", \"1957\": \"01-31\", \"1958\": \"02-18\", \"1959\": \"02-08\", \"1960\": \"01-28\", \"1961\": \"02-15\", \"1962\": \"02-05\", \"1963\": \"01-25\", \"1964\": \"02-13\", \"1965\": \"02-02\", \"1966\": \"01-21\", \"1967\": \"02-09\", \"1968\": \"01-30\", \"1969\": \"02-17\", \"1970\": \"02-06\", \"1971\": \"01-27\", \"1972\": \"02-15\", \"1973\": \"02-03\", \"1974\": \"01-23\", \"1975\": \"02-11\", \"1976\": \"01-31\", \"1977\": \"02-18\", \"1978\": \"02-07\", \"1979\": \"01-28\", \"1980\": \"02-16\", \"1981\": \"02-05\", \"1982\": \"01-25\", \"1983\": \"02-13\", \"1984\": \"02-02\", \"1985\": \"02-20\", \"1986\": \"02-09\", \"1987\": \"01-29\", \"1988\": \"02-17\", \"1989\": \"02-06\", \"1990\": \"01-27\", \"1991\": \"02-15\", \"1992\": \"02-04\", \"1993\": \"01-23\", \"1994\": \"02-10\", \"1995\": \"01-31\", \"1996\": \"02-19\", \"1997\": \"02-07\", \"1998\": \"01-28\", \"1999\": \"02-16\", \"2000\": \"02-05\", \"2001\": \"01-24\", \"2002\": \"02-12\", \"2003\": \"02-01\", \"2004\": \"01-22\", \"2005\": \"02-09\", \"2006\": \"01-29\", \"2007\": \"02-18\", \"2008\": \"02-07\", \"2009\": \"01-26\", \"2010\": \"02-14\", \"2011\": \"02-03\", \"2012\": \"01-23\", \"2013\": \"02-10\", \"2014\": \"01-31\", \"2015\": \"02-19\", \"2016\": \"02-08\", \"2017\": \"01-28\", \"2018\": \"02-16\", \"2019\": \"02-05\", \"2020\": \"01-25\", \"2021\": \"02-12\", \"2022\": \"02-01\", \"2023\": \"01-22\", \"2024\": \"02-10\", \"2025\": \"01-29\", \"2026\": \"02-17\", \"2027\": \"02-06\", \"2028\": \"01-26\", \"2029\": \"02-13\", \"2030\": \"02-03\", \"2031\": \"01-23\", \"2032\": \"02-11\"};\nvar INI=[[3,21],[4,20],[5,21],[6,21],[7,23],[8,23],[9,23],[10,23],[11,22],[12,22],[1,20],[2,19]];\nfunction q(s,r){return (r||P).querySelector(s)}function qa(s,r){return [].slice.call((r||P).querySelectorAll(s))}\n// medallones: los mismos de las tarjetas diarias\nqa('[data-med]').forEach(function(el){if(el.firstChild)return;var s=document.querySelector('#signo-'+el.getAttribute('data-med')+' svg.medallon');if(!s)return;\nvar c=s.cloneNode(true),t=el.getAttribute('data-tam')||'40';c.setAttribute('width',t);c.setAttribute('height',t);c.setAttribute('aria-hidden','true');\nc.setAttribute('focusable','false');c.removeAttribute('role');c.removeAttribute('aria-label');c.removeAttribute('id');el.appendChild(c)});\nfunction vista(v){H.setAttribute('data-vista',v);qa('.horo-btn',H).forEach(function(b){b.setAttribute('aria-pressed',String(b.getAttribute('data-v')===v))})}\nqa('.horo-btn',H).forEach(function(b){b.addEventListener('click',function(){vista(b.getAttribute('data-v'))})});\n// estado del perfil: d, m, y (nacimiento), s (signo 0-11), a (animal 0-11), e (elemento 0-4: Madera, Fuego, Tierra, Metal, Agua)\nvar E={d:0,m:0,y:0,s:-1,a:-1,e:-1};\nfunction num(v,a,b){v=+v;return (isFinite(v)&&v>=a&&v<=b&&Math.floor(v)===v)?v:null}\nfunction leer(){try{var o=JSON.parse(localStorage.getItem('cn-perfil')||'null');if(o&&typeof o==='object'){E.d=num(o.d,1,31)||0;E.m=num(o.m,1,12)||0;E.y=num(o.y,1900,ANIO)||0;\nvar s=num(o.s,0,11),a=num(o.a,0,11),e=num(o.e,0,4);E.s=s===null?-1:s;E.a=a===null?-1:a;E.e=e===null?-1:e}\nelse{var g=localStorage.getItem('cn-signo');if(g&&/^(?:[0-9]|1[01])$/.test(g))E.s=+g}}catch(x){}}\nfunction guardar(){try{if(E.d||E.m||E.y||E.s>=0||E.a>=0||E.e>=0)localStorage.setItem('cn-perfil',JSON.stringify(E));else localStorage.removeItem('cn-perfil');localStorage.removeItem('cn-signo')}catch(x){}}\nfunction red(n){while(n>9&&n!==11&&n!==22){n=String(n).split('').reduce(function(a,c){return a+(+c)},0)}return n}\nfunction sumad(n){return String(n).split('').reduce(function(a,c){return a+(+c)},0)}\nfunction diasMes(m,y){return [31,(y&&!((y%4===0&&y%100!==0)||y%400===0))?28:29,31,30,31,30,31,31,30,31,30,31][m-1]}\nfunction fechaOk(){return E.d&&E.m&&E.d<=diasMes(E.m,E.y)}\nfunction signoDe(m,d){var k=m*100+d,i,best=9,bk=-1;for(i=0;i<12;i++){var v=INI[i][0]*100+INI[i][1];if(v<=k&&v>bk){bk=v;best=i}}return best}\nfunction cuspide(){if(!fechaOk())return -1;var y=2001,t=new Date(y,E.m-1,E.d),s=signoDe(E.m,E.d);\nvar a=new Date(y,E.m-1,E.d-1),b=new Date(y,E.m-1,E.d+1),sa=signoDe(a.getMonth()+1,a.getDate()),sb=signoDe(b.getMonth()+1,b.getDate());return sa!==s?sa:(sb!==s?sb:-1)}\nfunction anioChino(){var c=CNY[E.y];if(!c)return E.y;var cm=+c.slice(0,2),cd=+c.slice(3);return (E.m<cm||(E.m===cm&&E.d<cd))?E.y-1:E.y}\nfunction derivar(){if(!fechaOk())return;E.s=signoDe(E.m,E.d);if(E.y){var cy=anioChino();E.a=((cy-4)%12+12)%12;E.e=[3,3,4,4,0,0,1,1,2,2][cy%10]}}\nfunction marcar(){qa('.ha-zod .ha-signo').forEach(function(x){x.classList.toggle('ha-sel',+x.getAttribute('data-i')===E.s)});\nqa('.ha-zod .ha-chip').forEach(function(b){b.setAttribute('aria-pressed',String(+b.getAttribute('data-i')===E.s))});\nqa('.ha-chi .hc-animal').forEach(function(x){x.classList.toggle('ha-sel',+x.getAttribute('data-a')===E.a)});\nqa('.ha-chi .ha-chip').forEach(function(b){b.setAttribute('aria-pressed',String(+b.getAttribute('data-a')===E.a))});\nqa('.ha-zod').forEach(function(z){z.classList.toggle('ha-con',E.s>=0)});qa('.ha-chi').forEach(function(z){z.classList.toggle('ha-con',E.a>=0)});\nqa('.hp-d').forEach(function(s){s.value=E.d?String(E.d):''});qa('.hp-m').forEach(function(s){s.value=E.m?String(E.m):''});qa('.hp-y').forEach(function(s){s.value=E.y?String(E.y):''});\nqa('.hp-s').forEach(function(s){s.value=E.s>=0?String(E.s):''});qa('.hp-a').forEach(function(s){s.value=E.a>=0?String(E.a):''});qa('.hp-e').forEach(function(s){s.value=E.e>=0?String(E.e):''});\nqa('.ha-bloque').forEach(resumen)}\nfunction cap(t){t=String(t||'');t=t.charAt(0).toUpperCase()+t.slice(1);return /[.!?]$/.test(t)?t:t+'.'}function esc(t){return String(t).replace(/[&<>\"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]})}\nfunction est(n,T){n=+n||0;return '<span class=\"estr\" aria-label=\"'+n+' '+T.de+' 5\">'+'★★★★★'.slice(0,n)+'<span class=\"apag\">'+'★★★★★'.slice(0,5-n)+'</span></span>'}\nfunction resumen(bl){var r=q('.hp-res',bl),dj=q('.hp-datos',bl);if(!r||!dj)return;var D;try{D=JSON.parse(dj.textContent)}catch(x){return}var T=D.t,h='',n=0;\nif(E.s>=0){var a=q('.ha-signo[data-i=\"'+E.s+'\"]',bl),de=a?q('.destacada',a):null,es=((a&&a.getAttribute('data-estr'))||'0,0,0').split(','),cu=cuspide();n++;\nh+='<div class=\"hp-i\"><span class=\"hp-k\">'+T.signo+'</span><b>'+esc(D.signos[E.s])+'</b>'+(de?'<span class=\"hp-d\">'+esc(de.textContent)+'</span>':'')\n+'<span class=\"hp-s\">'+T.amor+' '+est(es[0],T)+' · '+T.dinero+' '+est(es[1],T)+' · '+T.salud+' '+est(es[2],T)+'</span>'\n+(cu>=0&&cu!==E.s?'<span class=\"hp-d\">'+esc(T.cuspide.replace('{a}',D.signos[E.s]).replace('{b}',D.signos[cu]))+'</span>':'')\n+'<button type=\"button\" class=\"hp-ir\" data-ir=\"anio\">'+T.ver+'</button></div>'}\nif(E.a>=0){var c=q('.hc-animal[data-a=\"'+E.a+'\"]',bl),dc=c?q('.destacada',c):null,ec=((c&&c.getAttribute('data-areas'))||'0,0,0').split(','),eg=c?c.getAttribute('data-estr'):'0';n++;\nh+='<div class=\"hp-i\"><span class=\"hp-k\">'+T.chino+'</span><b><span class=\"hc-glifo hc-mini\" aria-hidden=\"true\">'+D.glifos[E.a]+'</span> '+esc(D.animales[E.a])+(E.e>=0?' '+esc(T.de_elem.replace('{e}',D.elems[E.e])):'')+'</b>'\n+'<span class=\"hp-d\">'+esc((c&&c.getAttribute('data-rel'))||'')+' '+est(eg,T)+'</span>'+(dc?'<span class=\"hp-d\">'+esc(dc.textContent)+'</span>':'')\n+'<span class=\"hp-s\">'+T.amor+' '+est(ec[0],T)+' · '+T.dinero+' '+est(ec[1],T)+' · '+T.salud+' '+est(ec[2],T)+'</span>'\n+'<button type=\"button\" class=\"hp-ir\" data-ir=\"chino\">'+T.ver+'</button></div>'}\nif(E.e>=0){n++;h+='<div class=\"hp-i\"><span class=\"hp-k\">'+T.elemento+'</span><b>'+esc(D.elems[E.e])+'</b><span class=\"hp-d\">'+esc(D.nac[E.e])+'</span></div>'}\nif(fechaOk()){var u=red(sumad(ANIO)),pa=red(red(E.d)+red(E.m)+u);n++;\nh+='<div class=\"hp-i\"><span class=\"hp-k\">'+T.numero+'</span><b>'+esc(T.anop.replace('{n}',pa))+'</b><span class=\"hp-d\">'+esc(cap(D.num[pa]))+'</span>';\nif(E.y){var v=red(red(E.d)+red(E.m)+red(sumad(E.y)));h+='<b class=\"hp-b2\">'+esc(T.vida.replace('{n}',v))+'</b><span class=\"hp-d\">'+esc(cap(D.vida[v]))+'</span>'}h+='</div>'}\nr.innerHTML=n?'<p class=\"hp-res-t\">'+esc(T.tit)+'</p><div class=\"hp-res-g\">'+h+'</div>':'<p class=\"hp-vacio\">'+esc(T.vacio)+'</p>'}\nfunction cambiar(){guardar();marcar()}\nP.addEventListener('change',function(ev){var t=ev.target;if(!t||!t.classList)return;var v=t.value===''?null:+t.value;\nif(t.classList.contains('hp-d')||t.classList.contains('hp-m')||t.classList.contains('hp-y')){var k=t.classList.contains('hp-d')?'d':(t.classList.contains('hp-m')?'m':'y');E[k]=v||0;derivar();cambiar();return}\nif(t.classList.contains('hp-s')){E.s=v===null?-1:v;cambiar();return}if(t.classList.contains('hp-a')){E.a=v===null?-1:v;cambiar();return}if(t.classList.contains('hp-e')){E.e=v===null?-1:v;cambiar();return}});\nfunction irA(el){if(!el)return;var r=el.getBoundingClientRect();if(r.top>innerHeight*0.7||r.top<0)el.scrollIntoView({block:'start',behavior:(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches)?'auto':'smooth'})}\nP.addEventListener('click',function(ev){var t=ev.target&&ev.target.closest?ev.target:null;if(!t)return;var b=t.closest('.ha-chip'),bl=t.closest('.ha-bloque');\nif(b){if(b.hasAttribute('data-i')){E.s=+b.getAttribute('data-i');cambiar();irA(q('.ha-signo[data-i=\"'+E.s+'\"]',bl))}else{E.a=+b.getAttribute('data-a');cambiar();irA(q('.hc-animal[data-a=\"'+E.a+'\"]',bl))}return}\nvar ir=t.closest('.hp-ir');if(ir){var v=ir.getAttribute('data-ir');vista(v);setTimeout(function(){irA(v==='anio'?q('.ha-signo[data-i=\"'+E.s+'\"]',bl):q('.hc-animal[data-a=\"'+E.a+'\"]',bl))},30);return}\nif(t.closest('.hp-borrar')){E={d:0,m:0,y:0,s:-1,a:-1,e:-1};cambiar()}});\nfunction idioma(l){var en=/^en/i.test(String(l||R.lang||''));H.classList.toggle('cn-en',en);qa('.ha-bloque').forEach(function(b){if((b.getAttribute('lang')==='en')!==en)b.setAttribute('aria-hidden','true');else b.removeAttribute('aria-hidden')})}\nidioma(R.lang);document.addEventListener('cofrade-idioma',function(e){idioma(e&&e.detail)});\nleer();marcar();\n// el buscador de la edición: si un resultado cae aquí adentro, se abre la vista que lo muestra\nif('MutationObserver' in window)new MutationObserver(function(ms){for(var k=0;k<ms.length;k++){var el=ms[k].target;if(!el.classList||!el.classList.contains('cn-flash'))continue;\nvar z=el.closest('.ha-zod'),c=el.closest('.ha-chi'),a=el.closest('.ha-signo'),b=el.closest('.hc-animal');\nif(z&&H.getAttribute('data-vista')!=='anio')vista('anio');if(c&&H.getAttribute('data-vista')!=='chino')vista('chino');\nif(a){E.s=+a.getAttribute('data-i');marcar()}if(b){E.a=+b.getAttribute('data-a');marcar()}setTimeout(function(){try{el.scrollIntoView({block:'center'})}catch(x){}},40);break}})\n.observe(P,{attributes:true,attributeFilter:['class'],subtree:true});\n})();</script>";
function anioHoroscopo(fecha) {
  const y = Number(String(fecha).slice(0, 4)), m = Number(String(fecha).slice(5, 7));
  return m >= 11 ? y + 1 : y;
}
function horoscopoAnual(fecha) {
  const anio = anioHoroscopo(fecha), panel = HORO_ANUAL[anio] || "";
  let boton = false, puesto = false;
  const b = (v, es, en) => `<button type="button" class="moneda horo-btn" data-v="${v}" aria-pressed="false" aria-controls="horoAnual" data-no-tr><span class="mn">`
    + `<span class="ha-l-es">${es}</span><span class="ha-l-en" lang="en">${en}</span></span></button>`;
  return {
    cabeza: { element(e) { e.append(HORO_ANUAL_CSS, { html: true }); } },
    vista: { element(e) {
      if (!panel || boton) return;
      boton = true;
      e.setAttribute("class", `${e.getAttribute("class") || ""} cn-cuatro`.trim());
      e.append(b("anio", `Horóscopo año ${anio}`, `${anio} Horoscope`) + b("chino", `Horóscopo chino ${anio}`, `${anio} Chinese Horoscope`), { html: true });
    } },
    signos: { element(e) { if (!panel || !boton || puesto) return; puesto = true; e.after(panel, { html: true }); } },
    cuerpo: { element(e) { e.onEndTag((t) => { if (puesto) t.before(HORO_ANUAL_JS, { html: true }); }); } },
  };
}

// 19-11-2026 · «Proyección de crecimiento en Chile durante los próximos 4 años» (Germán, 15:27: «agregar después de la sección
// "Crecimiento de Chile 2026: ¿cuánto crecerá la economía?" y antes de la sección "Perspectivas de Desarrollo para Chile 2050" una nueva
// sección… basándote en el Banco Central de Chile y junto con los principales Organismos internacionales que analizan esta información
// para publicar gráficos y noticias que detallen cuál es la tendencia y los indicadores esperados durante los próximos años»).
// Los datos los arma GitHub cada día (bajar.py → datos/proyecciones-chile.json): el FMI desde su base de datos oficial, la Encuesta de
// Expectativas desde el Banco Central, las demás instituciones verificadas con fecha y enlace, y las noticias de los titulares del día.
// Aquí se arma el bloque (español e inglés) justo después de «Crecimiento de Chile»; los gráficos los dibuja el navegador
// (modulos/proyeccion_cliente.js), que además suma el tema al Índice. Si el archivo no llega o viene incompleto, la edición queda como
// salió (nunca un bloque vacío). Va desde la edición del 19-11-2026: las anteriores quedan tal como se publicaron.
const PROY_DESDE = "2026-11-19";
const PROY_META = 3;   // meta de inflación del Banco Central de Chile (3 % anual)
const PROY_MESES = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"];
const PROY_MESES_EN = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

function pcEsc(s) { return String(s == null ? "" : s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]); }
function pcLimpio(t) {   // menos tipográfico → «-»; «2-3» → «2 a 3» (un rango, no 2 y −3)
  return String(t == null ? "" : t).replace(/[−–]/g, "-").replace(/(\d)\s*-\s*(?=\d)/g, "$1 a ");
}
function pcNum(t) {   // «0,25 a 0,75» → 0,5 (centro del rango); «2,4» o «2.4» → 2,4; «-1,8» → -1,8
  const xs = pcLimpio(t).match(/-?\d+(?:[.,]\d+)?/g);
  if (!xs) return null;
  const v = xs.slice(0, 2).map((x) => Number(x.replace(",", ".")));
  return v.every(Number.isFinite) ? v.reduce((a, b) => a + b, 0) / v.length : null;
}
function pcRango(t) {   // «2 a 3» → [2, 3]; un solo número → null
  const xs = pcLimpio(t).match(/-?\d+(?:[.,]\d+)?/g);
  return xs && xs.length >= 2 ? [Number(xs[0].replace(",", ".")), Number(xs[1].replace(",", "."))] : null;
}
function pcFmt(v, en, dec = 1) {   // 2.5 → «2,5 %» / «2.5%»; -0.4 → «−0,4 %» (redondeo igual para positivos y negativos)
  if (v == null || !Number.isFinite(v)) return "";
  const r = Math.sign(v) * Math.round(Math.abs(v) * 10 ** dec) / 10 ** dec, a = Math.abs(r).toFixed(dec);
  return (r < 0 ? "−" : "") + (en ? a + "%" : a.replace(".", ",") + " %");
}
function pcFmtL(v, en) {   // con la precisión publicada: 4,25 → «4,25 %»; 4,5 → «4,5 %»
  if (v == null || !Number.isFinite(v)) return "";
  const a = String(Math.round(Math.abs(v) * 100) / 100);
  return (v < 0 ? "−" : "") + (en ? a + "%" : a.replace(".", ",") + " %");
}
function pcCelda(t, en) {   // como lo publicó la institución: «2 a 3» → «2–3»; «2,7» → «2,7» (inglés: «2.7»); lo que no es número, vacío
  const s = String(t == null ? "" : t).trim();
  if (!s) return "";
  const r = pcRango(s), n = pcNum(s);
  if (!r && n == null) return "";
  const f = (x) => { const a = Math.abs(x).toString(); return (x < 0 ? "−" : "") + (en ? a : a.replace(".", ",")); };
  return r ? f(r[0]) + "–" + f(r[1]) : f(n);
}
function pcMes(iso) {   // «2026-11-…» → 10 (índice del mes) o -1 si no es una fecha válida
  const m = String(iso || "").match(/^\d{4}-(\d{2})/), k = m ? Number(m[1]) - 1 : -1;
  return k >= 0 && k < 12 ? k : -1;
}
function pcFecha(iso, en) {   // «2026-11-19» → «19 de noviembre de 2026» / «November 19, 2026»
  const m = String(iso || "").match(/^(\d{4})-(\d{2})-(\d{2})/), k = pcMes(iso);
  if (!m || k < 0) return "";
  return en ? `${PROY_MESES_EN[k]} ${Number(m[3])}, ${m[1]}` : `${Number(m[3])} de ${PROY_MESES[k]} de ${m[1]}`;
}
function pcFechaCorta(iso, en) {   // «2026-11-18» → «18 nov» / «Nov 18»
  const m = String(iso || "").match(/^(\d{4})-(\d{2})-(\d{2})/), k = pcMes(iso);
  if (!m || k < 0) return "";
  return en ? `${PROY_MESES_EN[k].slice(0, 3)} ${Number(m[3])}` : `${Number(m[3])} ${PROY_MESES[k].slice(0, 3)}`;
}
function pcMesInforme(x, en) {   // fecha del informe para leer: «septiembre de 2026» / «September 2026»
  if (en && x.fecha_texto_en) return String(x.fecha_texto_en);
  if (!en && x.fecha_texto) return String(x.fecha_texto);
  const m = String(x.fecha || "").match(/^(\d{4})-/), k = pcMes(x.fecha);
  return m && k >= 0 ? (en ? `${PROY_MESES_EN[k]} ${m[1]}` : `${PROY_MESES[k]} de ${m[1]}`) : "";
}

function proyeccionValida(d) {
  if (!d || typeof d !== "object" || !Array.isArray(d.instituciones) || !Array.isArray(d.anios) || d.anios.length < 4) return false;
  if (!Number.isInteger(d.anio_base) || !d.anios.slice(0, 4).every((a, i) => String(a) === String(d.anio_base + 1 + i))) return false;   // años de verdad, en orden
  const a1 = d.anios[0], p = d.promedio || {};
  return d.instituciones.filter((x) => x && x.activo !== false).length >= 3 && !!p[a1] && Number.isFinite(p[a1].valor) && Number.isFinite(p[a1].n);
}

async function proyeccionLeer(fecha, ctx) {
  if (!fecha || fecha < PROY_DESDE) return null;
  try {
    // Cada edición lee la foto de su fecha (datos/proyecciones/AAAA-MM-DD.json): una edición pasada no cambia nunca. La de hoy, si su
    // foto aún no está, usa el archivo del día. Un «no está» se recuerda 2 minutos para no preguntarle a GitHub en cada visita.
    const hoy = fechaChile(), neg = new Request("https://cache.cofrad.es/neg/proyecciones/" + fecha);
    let r = null;
    if (!(await caches.default.match(neg))) {
      r = await desdeGitHub(`datos/proyecciones/${fecha}.json`, fecha < hoy ? 86400 : 1800, ctx);
      if (!r) ctx.waitUntil(caches.default.put(neg, new Response("0", { headers: { "Cache-Control": "public, max-age=120" } })).catch(() => {}));
    }
    if (!r && fecha === hoy) r = await desdeGitHub("datos/proyecciones-chile.json", 1800, ctx);
    if (!r) return null;
    const ver = String(r.headers.get("X-Cn-Fuente") || r.headers.get("X-Cn-Guardado") || "").replace(/[^\w.-]/g, "").slice(0, 40);
    const d = await r.json();
    return proyeccionValida(d) ? { d, ver } : null;
  } catch (e) {
    return null;
  }
}

// Las cifras que usan el bloque y los gráficos (una sola cuenta para los dos idiomas)
function proyeccionCifras(d) {
  const base = Number(d.anio_base), anios = [String(base), ...d.anios.slice(0, 4).map(String)];
  const inst = d.instituciones.filter((x) => x && x.clave && x.pib && x.activo !== false);   // las de hace más de ~6 meses no se muestran
  const prom = d.promedio || {};
  const puntos = [];
  for (const x of inst) for (const a of anios) {
    const v = pcNum((x.pib || {})[a]);
    if (v == null) continue;
    puntos.push({ k: x.clave, n: x.corto || x.institucion, ne: x.corto_en || x.corto || x.institucion, a, v, r: pcRango((x.pib || {})[a]), bc: x.clave === "bcch_ipom" });
  }
  const consenso = anios.map((a) => (prom[a] && Number.isFinite(prom[a].valor) ? { a, v: prom[a].valor, min: prom[a].min, max: prom[a].max, n: prom[a].n } : null)).filter(Boolean);
  const infl = {};
  for (const a of anios) {
    const vs = inst.map((x) => pcNum((x.inflacion || {})[a])).filter((v) => v != null);
    if (vs.length) infl[a] = { v: vs.reduce((s, v) => s + v, 0) / vs.length, n: vs.length };
  }
  const fmi = (d.fmi && d.fmi.series) || {};
  return { base, anios, inst, prom, puntos, consenso, infl, fmi };
}

function proyeccionKpis(c, en) {
  const [a0, a1, a2, a3, a4] = c.anios, P = c.prom, k = [];
  const kpi = (n, v, dd) => `<div class="kpi"><span class="kn">${pcEsc(n)}</span><span class="kv">${pcEsc(v)}</span><span class="kd">${pcEsc(dd)}</span></div>`;
  const rango = (p) => (p.n > 1 ? (en ? `range ${pcFmt(p.min, true)} to ${pcFmt(p.max, true)}` : `rango ${pcFmt(p.min, false).replace(" %", "")} a ${pcFmt(p.max, false)}`) : "");
  const quien = (p) => (p.n === 1 ? (en ? "one institution" : "una institución") : en ? `average of ${p.n} institutions` : `promedio de ${p.n} instituciones`);
  for (const a of [a1, a2]) if (P[a]) k.push(kpi(en ? `GDP growth ${a}` : `Crecimiento del PIB ${a}`, pcFmt(P[a].valor, en), [quien(P[a]), rango(P[a])].filter(Boolean).join(" · ")));
  if (P[a1] && P[a2] && P[a3] && P[a4]) {   // cuánto más grande sería la economía en 4 años si se cumple el promedio de cada año
    const acum = ([a1, a2, a3, a4].reduce((x, a) => x * (1 + P[a].valor / 100), 1) - 1) * 100;
    const solos = [a1, a2, a3, a4].filter((a) => P[a].n === 1), lista = solos.length > 1 ? solos.slice(0, -1).join(", ") + (en ? " and " : " y ") + solos[solos.length - 1] : solos.join("");
    k.push(kpi(en ? `Cumulative growth ${a1}–${a4}` : `Crecimiento acumulado ${a1}–${a4}`, (acum >= 0 ? "+" : "") + pcFmt(acum, en),
      en ? `if each year's average holds${solos.length ? ` (${lista}: IMF only)` : ""}` : `si se cumple el promedio de cada año${solos.length ? ` (${lista}: solo FMI)` : ""}`));
  }
  const inf = c.infl[a1];
  if (inf && inf.n >= 2) k.push(kpi(en ? `Inflation ${a1}` : `Inflación ${a1}`, pcFmt(inf.v, en), en ? `average of ${inf.n} · Central Bank target: 3%` : `promedio de ${inf.n} · meta del Banco Central: 3 %`));
  else if (P[a0]) k.push(kpi(en ? `GDP growth ${a0}` : `Crecimiento del PIB ${a0}`, pcFmt(P[a0].valor, en), quien(P[a0])));
  return k.length >= 3 ? `<div class="kpis">${k.join("")}</div>` : "";
}

function proyeccionResumen(c, d, en) {
  const [a0, a1, a2, a3, a4] = c.anios, P = c.prom, f = (v) => pcFmt(v, en), o = [];
  if (P[a1] && P[a2]) {
    o.push(en ? `Institutions expect Chile's economy to grow ${f(P[a1].valor)} in ${a1} and ${f(P[a2].valor)} in ${a2}`
      : `Las instituciones esperan que la economía chilena crezca ${f(P[a1].valor)} en ${a1} y ${f(P[a2].valor)} en ${a2}`);
    if (P[a0]) o[0] += en ? `, after ${f(P[a0].valor)} in ${a0}.` : `, después de ${f(P[a0].valor)} en ${a0}.`;
    else o[0] += ".";
  }
  if (P[a3] && P[a4]) {
    const solo = P[a3].n === 1 && P[a4].n === 1;
    const igual = f(P[a3].valor) === f(P[a4].valor);
    o.push(en ? `For ${a3} and ${a4}${solo ? ", the IMF projects" : ", the projections point to"} ${igual ? f(P[a3].valor) + " in both years" : f(P[a3].valor) + " and " + f(P[a4].valor)}.`
      : `Para ${a3} y ${a4}${solo ? ", el FMI proyecta" : ", las proyecciones apuntan a"} ${igual ? f(P[a3].valor) + " en ambos años" : f(P[a3].valor) + " y " + f(P[a4].valor)}.`);
  }
  const inf = c.infl[a1];
  if (inf && inf.n >= 2) {
    const dif = inf.v - PROY_META;
    const donde = Math.abs(dif) <= 0.3 ? (en ? "close to" : "cerca de") : dif > 0 ? (en ? "above" : "sobre") : (en ? "below" : "bajo");
    o.push(en ? `Inflation in ${a1} would be around ${f(inf.v)}, ${donde} the Central Bank's 3% target.` : `La inflación de ${a1} rondaría ${f(inf.v)}, ${donde} la meta de 3 % del Banco Central.`);
  }
  const t = d.tpm_esperada && Array.isArray(d.tpm_esperada.trayectoria) ? d.tpm_esperada.trayectoria.filter((x) => Array.isArray(x) && Number.isFinite(x[1])) : [];
  if (t.length >= 2) {
    const ult = t[t.length - 1], m = String(ult[0]).match(/^(\d{4})-(\d{2})/);
    if (m && pcMes(ult[0]) >= 0 && Number.isFinite(t[0][1])) {
      const cuando = en ? `${PROY_MESES_EN[Number(m[2]) - 1]} ${m[1]}` : `${PROY_MESES[Number(m[2]) - 1]} de ${m[1]}`;
      const g = (v) => pcFmtL(v, en), dif = ult[1] - t[0][1];
      o.push(Math.abs(dif) < 0.01
        ? (en ? `Economists surveyed by the Central Bank expect the monetary policy rate to stay at ${g(ult[1])} through ${cuando}.`
          : `Los economistas que encuesta el Banco Central esperan que la tasa de política monetaria se mantenga en ${g(ult[1])} hasta ${cuando}.`)
        : (en ? `Economists surveyed by the Central Bank expect the monetary policy rate to ${dif < 0 ? "fall" : "rise"} from ${g(t[0][1])} this month to ${g(ult[1])} by ${cuando}.`
          : `Los economistas que encuesta el Banco Central esperan que la tasa de política monetaria ${dif < 0 ? "baje" : "suba"} de ${g(t[0][1])} este mes a ${g(ult[1])} hacia ${cuando}.`));
    }
  }
  return o.length ? `<p class="pc-resumen"><b>${en ? "In short:" : "En resumen:"}</b> ${pcEsc(o.join(" "))}</p>` : "";
}

function proyeccionTablaInst(c, en) {
  const filas = c.inst.map((x) => {
    const inf = pcMesInforme(x, en) || "", via = x.via ? (en ? ` (via ${x.via})` : ` (vía ${x.via})`) : "";
    const celdas = c.anios.map((a) => { const t = pcCelda((x.pib || {})[a], en); return `<td class="pc-n"${t ? "" : ` aria-label="${en ? "no projection" : "sin proyección"}"`}>${t ? pcEsc(t) : "·"}</td>`; }).join("");
    return `<tr><th scope="row"><b>${pcEsc(en ? x.corto_en || x.corto : x.corto)}</b><br><span class="pc-inf">${pcEsc(inf)}${pcEsc(via)}</span></th>${celdas}</tr>`;
  }).join("");
  const prom = c.anios.map((a) => `<td class="pc-n"><b>${c.prom[a] ? pcEsc(pcFmt(c.prom[a].valor, en).replace(/ ?%$/, "")) : "·"}</b></td>`).join("");
  return `<div class="tabla pc-tabla" data-voz="no"><table><caption>${en ? "GDP growth projections by institution (% per year)" : "Proyecciones de crecimiento del PIB por institución (% anual)"}</caption>`
    + `<thead><tr><th scope="col">${en ? "Institution and report" : "Institución e informe"}</th>${c.anios.map((a) => `<th scope="col" class="pc-n">${a}</th>`).join("")}</tr></thead>`
    + `<tbody>${filas}</tbody><tfoot><tr><th scope="row">${en ? "Average (reports from the last 6 months)" : "Promedio (informes de los últimos 6 meses)"}</th>${prom}</tr></tfoot></table></div>`;
}

function proyeccionTablaFmi(c, en) {
  const S = c.fmi, filas = [["pib", "Crecimiento del PIB (% anual)", "GDP growth (% per year)"], ["inflacion", "Inflación (% promedio del año)", "Inflation (% yearly average)"],
    ["desempleo", "Desempleo (% de la fuerza de trabajo)", "Unemployment (% of labor force)"], ["cuenta_corriente", "Cuenta corriente (% del PIB)", "Current account (% of GDP)"],
    ["deuda", "Deuda pública bruta (% del PIB)", "Gross public debt (% of GDP)"]].filter((f) => S[f[0]] && c.anios.some((a) => Number.isFinite(S[f[0]][a])));
  if (filas.length < 3) return "";
  const cuerpo = filas.map((f) => `<tr><td>${pcEsc(en ? f[2] : f[1])}</td>${c.anios.map((a) => { const v = S[f[0]][a]; return `<td class="pc-n">${Number.isFinite(v) ? pcEsc(pcFmt(v, en).replace(/ ?%$/, "")) : "·"}</td>`; }).join("")}</tr>`).join("");
  return `<div class="tabla pc-tabla" data-voz="no"><table><caption>${en ? "Indicators expected by the IMF for Chile" : "Indicadores esperados por el FMI para Chile"}</caption>`
    + `<thead><tr><th scope="col">${en ? "Indicator" : "Indicador"}</th>${c.anios.map((a) => `<th scope="col" class="pc-n">${a}</th>`).join("")}</tr></thead><tbody>${cuerpo}</tbody></table></div>`;
}

function proyeccionNoticias(d, en) {
  const n = (Array.isArray(d.noticias) ? d.noticias : []).filter((x) => x && x.titulo && /^https:\/\//.test(String(x.url || ""))).slice(0, 6);
  if (!n.length) return "";
  const li = n.map((x) => `<li><a class="pc-n-t" href="${pcEsc(x.url)}" target="_blank" rel="noopener">${pcEsc(x.titulo)}</a> <span class="fuente"><a href="${pcEsc(x.url)}" target="_blank" rel="noopener">${pcEsc(x.fuente || (en ? "Source" : "Fuente"))}</a> · ${pcEsc(pcFechaCorta(x.fecha, en))}</span></li>`).join("");
  return `<div class="pc-noticias"><h4 class="pc-h4">${en ? "News from these days" : "Noticias de estos días"}</h4><ul class="pc-notas">${li}</ul></div>`;
}

function proyeccionFuentes(c, d, en) {
  const L = c.inst.map((x) => {   // enlace solo si es https; sin «undefined» si falta un dato
    const t = pcEsc([en ? x.institucion_en || x.corto_en || x.institucion : x.institucion, en ? x.informe_en || x.informe : x.informe].filter(Boolean).join(": ") + (x.via ? (en ? ", via " : ", vía ") + x.via : ""));
    return /^https:\/\//.test(String(x.url || "")) ? `<a href="${pcEsc(x.url)}" target="_blank" rel="noopener">${t}</a>` : t;
  });
  if (d.fmi && /^https:\/\//.test(String(d.fmi.url || ""))) L.push(`<a href="${pcEsc(d.fmi.url)}" target="_blank" rel="noopener">${en ? "IMF DataMapper (official database)" : "FMI, base de datos oficial (DataMapper)"}</a>`);
  return `<p class="fuente">${en ? "Sources" : "Fuentes"}: ${L.join(" · ")}</p>`;
}

function proyeccionBloque(d, en) {
  const c = proyeccionCifras(d), [a0, a1, , , a4] = c.anios;
  const al = pcFecha(String(d.generado || "").slice(0, 10), en);
  const nombres = c.inst.map((x) => (en ? x.corto_en || x.corto : x.corto));
  const ley = en
    ? `<p class="pc-ley" aria-hidden="true"><span><i class="pc-l1"></i>Average of the institutions</span><span><i class="pc-l2"></i>Central Bank (IPoM, midpoint and range)</span><span><i class="pc-l3"></i>Other institutions</span></p>`
    : `<p class="pc-ley" aria-hidden="true"><span><i class="pc-l1"></i>Promedio de las instituciones</span><span><i class="pc-l2"></i>Banco Central (IPoM, punto medio y rango)</span><span><i class="pc-l3"></i>Otras instituciones</span></p>`;
  const ley2 = en
    ? `<p class="pc-ley" aria-hidden="true"><span><i class="pc-l2"></i>Inflation</span><span><i class="pc-l1"></i>Unemployment</span><span><i class="pc-lm"></i>3% inflation target</span></p>`
    : `<p class="pc-ley" aria-hidden="true"><span><i class="pc-l2"></i>Inflación</span><span><i class="pc-l1"></i>Desempleo</span><span><i class="pc-lm"></i>Meta de inflación de 3 %</span></p>`;
  const conFmi = c.fmi.inflacion && c.fmi.desempleo;
  const figs = `<div class="dos pc-dos"><figure class="pc-fig" data-voz="no"><figcaption class="sub tabtit"><b>${en ? "Expected GDP growth" : "Crecimiento esperado del PIB"}</b> ${en ? "(% per year; each dot is one institution)" : "(% anual; cada punto es una institución)"}</figcaption>${ley}<div class="pc-graf" data-g="pib" role="img" aria-label="${pcEsc(c.consenso.map((p) => `${p.a}: ${pcFmt(p.v, en)}`).join(", "))}"></div></figure>`
    + (conFmi ? `<figure class="pc-fig" data-voz="no"><figcaption class="sub tabtit"><b>${en ? "Inflation and unemployment according to the IMF" : "Inflación y desempleo según el FMI"}</b> ${en ? `(%; shaded from ${a0}: projection)` : `(%; sombreado desde ${a0}: proyección)`}</figcaption>${ley2}<div class="pc-graf" data-g="fmi" role="img" aria-label="${pcEsc(en ? "IMF: inflation and unemployment" : "FMI: inflación y desempleo")}"></div></figure>` : "")
    + `</div>`;
  const solo = c.anios.filter((a) => c.prom[a] && c.prom[a].n === 1), ys = solo.length === 2 ? solo.join(en ? " and " : " y ") : solo.join(", ");
  const leer = en
    ? `<p class="sub leer"><b>How to read:</b> the average uses the projections published in the last six months; when an institution gives a range (the Central Bank), its midpoint is used.${solo.length ? ` For ${ys} only the IMF publishes a projection.` : ""} The IMF figures and the Central Bank survey refresh automatically; the others change when each institution publishes a new report. Inflation mixes yearly averages and December figures, as each source publishes it.</p>`
    : `<p class="sub leer"><b>Cómo leer:</b> el promedio usa las proyecciones publicadas en los últimos seis meses; cuando una institución entrega un rango (el Banco Central), se toma el punto medio.${solo.length ? ` Para ${ys} solo el FMI publica una proyección.` : ""} Las cifras del FMI y la Encuesta del Banco Central se actualizan solas; las demás cambian cuando cada institución publica un informe nuevo. La inflación mezcla promedios del año y cifras a diciembre, tal como las publica cada fuente.</p>`;
  return `<div class="pc-l" lang="${en ? "en" : "es"}">`
    + `<p class="bloque-kick">${en ? `Central Bank and international organizations · figures as of ${pcEsc(al)}` : `Banco Central y organismos internacionales · cifras al ${pcEsc(al)}`}</p>`
    + `<h3 class="bloque-tit">${en ? "Chile's growth outlook for the next 4 years" : "Proyección de crecimiento en Chile durante los próximos 4 años"}</h3>`
    + `<p class="sub" data-voz="no">${pcEsc(en ? `What ${nombres.join(", ")} expect for ${a1} to ${a4}.` : `Qué esperan para ${a1} a ${a4}: ${nombres.join(", ")}.`)}</p>`
    + proyeccionResumen(c, d, en)
    + `<div data-voz="no">${proyeccionKpis(c, en)}</div>`
    + figs
    + proyeccionTablaInst(c, en)
    + proyeccionTablaFmi(c, en)
    + proyeccionNoticias(d, en)
    + leer
    + proyeccionFuentes(c, d, en)
    + `</div>`;
}

function proyeccionDatosGraf(d) {   // lo mínimo que necesitan los dos gráficos del navegador
  const c = proyeccionCifras(d), S = c.fmi, anios = c.anios, hist = [];
  for (let a = c.base - 3; a <= c.base + 5; a++) hist.push(String(a));
  const serie = (k) => { const o = {}; for (const a of hist) if (S[k] && Number.isFinite(S[k][a])) o[a] = S[k][a]; return o; };
  return { base: c.base, anios, meta: PROY_META, consenso: c.consenso, puntos: c.puntos.map((p) => ({ k: p.k, n: p.n, ne: p.ne, a: p.a, v: Math.round(p.v * 100) / 100, r: p.r, bc: p.bc || undefined })),
    fmi: { anios: hist, inflacion: serie("inflacion"), desempleo: serie("desempleo") } };
}

function proyeccionHtml(d) {
  const datos = JSON.stringify(proyeccionDatosGraf(d)).replace(/</g, "\\u003c");
  return `<div class="cr-bloque pc-bloque" id="proyw" data-no-tr>${proyeccionBloque(d, false)}${proyeccionBloque(d, true)}`
    + `<script type="application/json" class="pc-datos">${datos}</script></div>`;
}

